/* Bad: too specific and nested */
body div.container ul li a.link {
  color: blue;
}

/* Good: simple and reusable */
.link {
  color: blue;
}

/* Avoid: blocks parallel loading */
@import url('base.css');
@import url('layout.css');

<!-- Better: use link tags, they load in parallel -->
<link rel="stylesheet" href="base.css">
<link rel="stylesheet" href="layout.css">

/* Bad: specificity war */
#header .nav ul li a { color: blue !important; }
.nav a { color: red !important; }

/* Good: simple, low specificity, easy to override */
.nav-link { color: blue; }
